#!/usr/bin/env python3
"""Render real MockBukkit inventory snapshots; this is not a native game screenshot."""
from pathlib import Path
from PIL import Image,ImageDraw,ImageFont
import json,zipfile,base64,io,re,html,os
ROOT=Path(__file__).resolve().parents[2];OUT=Path(os.environ.get('UI_PREVIEW_OUTPUT',str(ROOT/'releases/ui-update')));OUT.mkdir(parents=True,exist_ok=True);snapshots=json.loads((ROOT/'interface-resourcepack/build/snapshots.json').read_text());(OUT/'menu-snapshots.json').write_text(json.dumps(snapshots,ensure_ascii=False,indent=2)+'\n')
with zipfile.ZipFile(ROOT/'releases/ui-update/CityEconomy-Interface-26.3-1.2.0.zip') as z:icons={n.removeprefix('assets/tycoon/textures/item/').removesuffix('.png'):z.read(n) for n in z.namelist() if n.startswith('assets/tycoon/textures/item/') and n.endswith('.png')}
fontpath=os.environ.get('UI_PREVIEW_FONT','C:/Windows/Fonts/malgun.ttf' if os.name=='nt' else '/usr/share/fonts/opentype/noto/NotoSansCJK-Regular.ttc');font=lambda n:ImageFont.truetype(fontpath,n,index=0 if os.name=='nt' else 1)
def plain(text):return re.sub('§.','',text)
def short(text):return re.sub(r'^\[[^]]+\]\s*','',plain(text))[:3]
board=Image.new('RGB',(1800,1160),'#101c24');d=ImageDraw.Draw(board);d.text((40,26),'도시 생활 수첩',font=font(38),fill='#eef4ec');d.text((42,86),'쉬프트+F · 도감 진행률 · 보유 수량 · 상태 필터 · 실제 보상 확인',font=font(21),fill='#68cdbb')
labels={'main':'마을 수첩 · 기능별 구분','codex':'수집 도감 · 분야별 진행','category':'등록 가능 / 미보유 구분','confirmation':'아이템 소비 · 실제 보상 확인','achievements':'업적 진행률 · 남은 목표','effects':'적용량 · 전체 상한 확인'}
for index,key in enumerate(labels):
 screen=snapshots[key];x=35+(index%3)*590;y=156+(index//3)*465;d.rounded_rectangle((x,y,x+555,y+440),radius=16,fill='#1a2b34',outline='#37515c');d.text((x+20,y+14),labels[key],font=font(23),fill='#dfeee7');d.text((x+20,y+48),screen['title'],font=font(16),fill='#96b3bc')
 for slot,entry in enumerate(screen['slots']):
  xx=x+33+(slot%9)*54;yy=y+82+(slot//9)*54;d.rounded_rectangle((xx,yy,xx+50,yy+50),radius=5,fill='#273e47',outline='#5ba899' if entry and entry['glow'] else '#36505b')
  if not entry:continue
  name=plain(entry['name']);model=entry.get('model');path=model.removeprefix('tycoon:') if model else None
  if path in icons:
   sprite=Image.open(io.BytesIO(icons[path])).convert('RGBA').resize((44,44),Image.Resampling.LANCZOS);board.paste(sprite,(xx+3,yy+3),sprite)
  elif name.strip():
   text=short(name);color='#72dfbc' if '등록 완료' in name else '#7ed8f1' if '등록 가능' in name else '#d9e2e5';bounds=d.textbbox((0,0),text,font=font(12));d.text((xx+(50-(bounds[2]-bounds[0]))/2,yy+17),text,font=font(12),fill=color)
 d.text((x+20,y+412),'실제 플러그인 슬롯 데이터 기반 · 게임 화면 캡처 아님',font=font(14),fill='#8dabb5')
d.text((40,1105),'전용 아이콘은 배포팩의 실제 PNG · 기본 아이템은 이름 타일로 표시 · HTML에서 설명을 펼쳐 볼 수 있습니다.',font=font(19),fill='#96b4bd');board.save(OUT/'메뉴-미리보기.png',optimize=True)
data={k:'data:image/png;base64,'+base64.b64encode(v).decode() for k,v in icons.items()}
page='''<!doctype html><html lang="ko"><meta charset="utf-8"><meta name="viewport" content="width=device-width"><title>도시 생활 수첩 UI 미리보기</title><style>
*{box-sizing:border-box}body{margin:0;background:#101c24;color:#e7f0eb;font:16px 'Malgun Gothic',sans-serif}main{max-width:1180px;margin:36px auto;padding:24px}h1{font-size:38px;margin:12px 0}p{line-height:1.8;color:#a4bcc5}.tag{color:#70d6c0}nav{display:flex;gap:8px;flex-wrap:wrap;margin:22px 0}button{font:inherit;color:inherit;background:#243c47;border:1px solid #45626c;border-radius:8px;padding:10px 14px;cursor:pointer}nav button.active{background:#246f68}.layout{display:grid;grid-template-columns:minmax(420px,600px) minmax(240px,1fr);gap:24px}.panel{padding:20px;background:#192e38;border-radius:16px;border:1px solid #35545e}h2{font-size:19px;margin:0 0 18px}#grid{display:grid;grid-template-columns:repeat(9,minmax(0,1fr));gap:5px}#grid button{aspect-ratio:1;padding:3px;min-width:0;overflow:hidden;background:#2b444f;border-radius:5px}#grid button.glow{border-color:#e0c85b;box-shadow:inset 0 0 8px #948842}#grid img{width:100%;height:100%;object-fit:contain}#grid small{font-size:11px;color:#b1c7cc}#detail{min-height:310px;overflow-wrap:anywhere}#detail p{margin:8px 0}#detail b{font-size:20px}#detail .state{color:#73d1b8}footer{color:#86a4ad;font-size:13px;margin-top:28px}@media(max-width:850px){.layout{grid-template-columns:1fr}main{padding:14px}#grid{gap:3px}.panel{padding:12px}}button:focus-visible{outline:3px solid #83e2ca;outline-offset:2px}</style>
<main><span class="tag">도시·경제풍 · JAVA 26.3</span><h1>도시 생활 수첩</h1><p>메뉴를 선택하고 아이콘에 마우스를 올리거나 클릭하면 실제 플러그인의 이름·설명을 확인할 수 있습니다.<br>MockBukkit에서 추출한 UI 구성 미리보기이며 실제 Minecraft 화면 캡처나 서버 접속 화면은 아닙니다.</p><nav id="nav"></nav><section class="layout"><div class="panel"><h2 id="title"></h2><div id="grid"></div></div><aside class="panel" id="detail"><b>아이콘을 선택하세요</b><p>필터·진행률·보유 수량·실제 보상 안내를 비교해 보세요.</p></aside></section><footer>전용 아이콘은 실제 통합팩 PNG입니다. 기본 Minecraft 아이템은 이름 타일로 표시합니다. 이 페이지에서는 게임 아이템이나 데이터를 변경하지 않습니다.</footer></main><script>'''
page+='const screens='+json.dumps(snapshots,ensure_ascii=False).replace('</','<\\/')+';const icons='+json.dumps(data)+';const labels='+json.dumps({**labels,'registered':'등록 완료 · 재소비 없음'},ensure_ascii=False)+';'
page+='''const strip=t=>(t||'').replace(/§./g,'');const esc=t=>t.replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));function detail(item){document.querySelector('#detail').innerHTML='<b>'+esc(strip(item.name))+'</b>'+item.lore.map(l=>'<p>'+esc(strip(l))+'</p>').join('')}
function show(key){document.querySelector('#title').textContent=screens[key].title;document.querySelectorAll('nav button').forEach(b=>b.classList.toggle('active',b.dataset.key===key));const grid=document.querySelector('#grid');grid.replaceChildren();screens[key].slots.forEach((item,i)=>{const button=document.createElement('button');button.dataset.slot=i;button.setAttribute('aria-label',item&&strip(item.name).trim()?strip(item.name):'빈칸');if(item){if(item.glow)button.className='glow';const model=(item.model||'').replace(/^tycoon:/,'');if(icons[model]){const img=document.createElement('img');img.src=icons[model];img.alt='';button.append(img)}else{const small=document.createElement('small');small.textContent=strip(item.name).replace(/^\\[[^\\]]+\\]\\s*/,'').slice(0,3);button.append(small)}button.onmouseenter=()=>detail(item);button.onfocus=()=>detail(item);button.onclick=()=>detail(item)}grid.append(button)})}
Object.entries(labels).forEach(([key,label])=>{const button=document.createElement('button');button.dataset.key=key;button.textContent=label;button.onclick=()=>show(key);document.querySelector('#nav').append(button)});show('main');</script></html>'''
(OUT/'메뉴-미리보기.html').write_text(page,encoding='utf-8');print('Rendered seven real UI snapshots and six-panel PNG')
